const data = $input.first().json;

const config = $('Set Requisition Parameters').first().json;

const amount = Number(data.estimatedTotalCost);

let approvalLevel = '';
let approverEmail = '';
let approvalReason = '';

if (amount <= Number(config.lowApprovalThreshold)) {
  approvalLevel = 'Low-Level Approval';
  approverEmail = data.budgetOwnerEmail;
  approvalReason = `Requisition amount is within the low approval threshold of ${config.currency} ${config.lowApprovalThreshold}.`;

} else if (amount <= Number(config.managerApprovalThreshold)) {
  approvalLevel = 'Manager Approval';
  approverEmail = data.budgetOwnerEmail;
  approvalReason = `Requisition amount requires manager approval because it exceeds the low approval threshold.`;

} else if (amount <= Number(config.financeApprovalThreshold)) {
  approvalLevel = 'Finance Approval';
  approverEmail = config.financeEmail;
  approvalReason = `Requisition amount requires finance approval because it exceeds the manager approval threshold.`;

} else {
  approvalLevel = 'High-Value Approval';
  approverEmail = config.financeEmail;
  approvalReason = `Requisition amount exceeds the finance approval threshold and requires high-value review.`;
}

return [
  {
    json: {
      ...data,
      approvalLevel,
      approverEmail,
      approvalReason,
      requestStatus: 'Pending Approval',
      approvalStatus: 'Pending',
      approvalDeterminedAt: new Date().toISOString(),
    },
  },
];

